<template><div class="analytics"><div class="heading"><div><h2>工单分析</h2><p>从状态、类别、优先级和处理时效观察报修闭环</p></div><el-button @click="refresh">刷新数据</el-button></div><el-row :gutter="16"><el-col :xs="24" :lg="14"><div class="chart-card"><h3>工单状态分布</h3><div id="repair-status" class="chart"></div></div></el-col><el-col :xs="24" :lg="10"><div class="chart-card"><h3>优先级占比</h3><div id="repair-priority" class="chart"></div></div></el-col><el-col :xs="24" :lg="14"><div class="chart-card"><h3>近 7 日工单趋势</h3><div id="repair-trend" class="chart"></div></div></el-col><el-col :xs="24" :lg="10"><div class="chart-card"><h3>维修类别数量</h3><div id="repair-category" class="chart"></div></div></el-col></el-row></div></template>
<script setup>
import { onMounted } from 'vue'; import * as echarts from 'echarts'
const charts=[]; const colors=['#2563eb','#0f9f78','#f59e0b','#ef4444','#8b5cf6']
const init=(id,opt)=>{const c=echarts.init(document.getElementById(id));c.setOption(opt);charts.push(c)}
const refresh=()=>{ charts.forEach(c=>c.resize()) }
onMounted(()=>{init('repair-status',{tooltip:{trigger:'item'},legend:{bottom:4},color:colors,series:[{type:'pie',radius:['48%','72%'],itemStyle:{borderRadius:6,borderColor:'#fff',borderWidth:3},label:{formatter:'{b}\n{c} 单'},data:[{name:'待处理',value:12},{name:'维修中',value:8},{name:'已完成',value:26},{name:'已取消',value:3}]}]});init('repair-priority',{tooltip:{trigger:'item'},color:['#ef4444','#2563eb'],series:[{type:'pie',radius:'70%',label:{formatter:'{b} {d}%'},data:[{name:'紧急',value:9},{name:'普通',value:40}]}]});init('repair-trend',{tooltip:{trigger:'axis'},legend:{bottom:0},grid:{left:35,right:18,top:20,bottom:35},xAxis:{type:'category',data:['周一','周二','周三','周四','周五','周六','周日']},yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf1f7'}}},series:[{name:'新建',type:'line',smooth:true,data:[8,12,9,15,13,18,16],itemStyle:{color:'#2563eb'},areaStyle:{color:'rgba(37,99,235,.12)'}},{name:'完成',type:'line',smooth:true,data:[5,8,7,10,12,14,15],itemStyle:{color:'#0f9f78'},areaStyle:{color:'rgba(15,159,120,.10)'}}]});init('repair-category',{tooltip:{trigger:'axis'},grid:{left:70,right:18,top:15,bottom:20},xAxis:{type:'value',splitLine:{show:false}},yAxis:{type:'category',data:['水电','门窗','消防','空调','其他']},series:[{type:'bar',data:[18,9,12,7,5],barWidth:16,itemStyle:{color:'#5b7cfa',borderRadius:[0,8,8,0]}}]})})
</script>
<style scoped>.analytics{padding:4px}.heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.heading h2{margin:0;color:#172033;font-size:22px}.heading p{margin:6px 0;color:#8491a5;font-size:13px}.chart-card{height:330px;margin-bottom:16px;padding:20px;background:#fff;border:1px solid #e7edf5;border-radius:12px;box-shadow:0 5px 18px rgba(31,55,90,.05)}h3{margin:0;color:#26364d;font-size:15px}.chart{height:285px}</style>
